-- Backs the "payrollRecords" collection (type PayrollRecord).
create table if not exists crm.payroll_records (
  id               text not null,
  org_id           text not null,
  employee_id      text,
  employee_name    text,
  employee_code    text,
  department       text,
  month            text,
  basic_salary     numeric,
  hra              numeric,
  allowances       numeric,
  bonuses          numeric,
  overtime         numeric,
  deductions       numeric,
  tax              numeric,
  net_salary       numeric,
  status           text, -- DRAFT | PAID | PROCESSED
  payment_date     date,
  payment_method   text,
  payslip_url      text,
  pf               numeric,
  esi              numeric,
  pt               numeric,
  lop_days         numeric,
  lop_amount       numeric,
  employer_pf      numeric,
  employer_esi     numeric,
  on_hold          boolean,
  hold_reason      text,
  _extra           jsonb not null default '{}'::jsonb, -- values that don't fit a typed column (kept losslessly)
  _position        double precision not null default 0, -- list order the app expects
  primary key (id)
);

